", "solution": "Square side=15; the triangle perimeter is 15+15+15sqrt(2).", "expected_key": "D", "source_image_checked": true, "scope": "Original source crop checked; independently recomputed current algebra and diagram result. Defective and ambiguous records excluded from this certified batch.", "repair": {}, "q_digest": "0c2fe3f560a2b56261cbd0822fdce2ff", "key_digest": "01a365ccd7fe89c2ef05e71b56850e6f", "fingerprint": "ea3bc34cb49d99b2e115dd20454172d3"}, {"id": "fa89e9b5-a841-5cba-b61b-ef39813d96f0", "status": "mathematically_verified", "solution": "Line L crosses the y-axis at 2/3. Substituting into D gives a=3/2, so its slope is -3/a=-2.", "expected_key": "A", "source_image_checked": true, "scope": "Original source crop checked; independently recomputed current algebra and diagram result. Defective and ambiguous records excluded from this certified batch.", "repair": {}, "q_digest": "7113143ddedd98d1016cf07601e2598c", "key_digest": "e71464b2d1dafb95b3adb34f19758df0", "fingerprint": "cf9baefbbb9a44cfcc80829bf11bfb55"}, {"id": "fdb00d7a-f3b3-5ee3-ad95-73d30e5a838c", "status": "mathematically_verified", "solution": "1+2+3+4+5=15; also 5*6/2=15.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop checked; independently recomputed current algebra and diagram result. Defective and ambiguous records excluded from this certified batch.", "repair": {}, "q_digest": "b794358af0e97163e6e5db352640c188", "key_digest": "81527c693af7c6885c3ad9279a17d20d", "fingerprint": "96359b38f49f73d4c2dace296540a043"}, {"id": "fdc2bf1d-4925-5626-a6c9-766d369f56d5", "status": "mathematically_verified", "solution": "-1/(2x-1)=sqrt(3) implies 2x-1=-1/sqrt(3), hence 6x=3-sqrt(3). Substitution returns sqrt(3).", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop checked; independently recomputed current algebra and diagram result. Defective and ambiguous records excluded from this certified batch.", "repair": {}, "q_digest": "214de3f2ed3ecac243bbd9c68fd665a0", "key_digest": "f395891ebe6556528c71d889bd54d792", "fingerprint": "f5882b7465f8515a3de0fc009840735a"}, {"id": "fecf4f9f-acea-5772-964c-dd4f1f2f8f3d", "status": "repair_and_verified", "solution": "The plotted values total 67 in 2012, 61 in 2013, and 70 in 2014. Their sum is 198 laptops.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop checked; independently recomputed current algebra and diagram result. Defective and ambiguous records excluded from this certified batch.", "repair": {"image": "https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-070-1.png", "stem": "The scatterplot shows laptop repairs for different companies in each year. What is the total number of laptops repaired in 2012, 2013 and 2014, including all three years?"}, "q_digest": "2b139872717648330490ae92a1e61740", "key_digest": "604bf7706b34bda017d093f75163cf2e", "fingerprint": "d5881f9b2ed7076218349431d22429c4"}, {"id": "ff6fa3bc-75db-5256-9dcc-3ed056df2cae", "status": "mathematically_verified", "solution": "The source contains a CUBE root. Cube both sides of −x = ∛x: −x³ = x, so x(x² + 1) = 0. The only real solution is x = 0, which satisfies the original equation. Therefore C.", "expected_key": "C", "source_image_checked": true, "scope": "Original source crop checked; independently recomputed current algebra and diagram result. Defective and ambiguous records excluded from this certified batch.", "repair": {}, "q_digest": "69a6a8c8b20f02083fc6a66f88d275d4", "key_digest": "ff3deab509aa7ff6b6b1daff9fb7fa32", "fingerprint": "4fae8f8a5d6fcbe6c050b1bf00a28c7a"}, {"id": "ffd401b8-d01b-53ba-ba12-aec01837279f", "status": "mathematically_verified", "solution": "Mass per meter=2/5 kg. Two meters weigh 2*(2/5)=0.8 kg.", "expected_key": "B", "source_image_checked": true, "scope": "Original source crop checked; independently recomputed current algebra and diagram result. Defective and ambiguous records excluded from this certified batch.", "repair": {}, "q_digest": "5fdd3e29e19e40c207ced46a2e909ffa", "key_digest": "9d361bbac7590be6b86a78c14b322b0a", "fingerprint": "3fb72e7235097785ccc451bf8a35c7df"}]'::jsonb)
as t(id uuid,status text,solution text,expected_key text,source_image_checked boolean,scope text,repair jsonb,q_digest text,key_digest text,fingerprint text,old_stem text);
do $$ begin
if exists(select 1 from audit_log where action='questions.est_remaining_batch08.20260930') then raise exception 'Batch already applied'; end if;
if (select count(*) from est_review_batch t join questions q on q.id=t.id join question_keys k on k.question_id=q.id where q.track_id='est' and md5(to_jsonb(q)::text)=t.q_digest and md5(to_jsonb(k)::text)=t.key_digest and k.correct#>>'{}'=t.expected_key and nullif(q.assets->>'release_hold_reason','') is null)<>77 then raise exception 'Reviewed question version changed'; end if;
end $$;
create temporary table est_review_revision_before on commit drop as
select r.question_id,r.active,r.fingerprint=t.fingerprint was_ready
from revision_items r join est_review_batch t on t.id=r.question_id;
insert into audit_log(action,target_type,target_id,meta)
select 'questions.est_remaining_batch08.20260930','question',q.id::text,
jsonb_build_object('previous_stem',q.stem,'previous_choices',q.choices,'previous_assets',q.assets,'previous_explanation',k.explanation,'solution',t.solution,'scope',t.scope,'source_image_checked',t.source_image_checked,'status',t.status)
from est_review_batch t join questions q on q.id=t.id join question_keys k on k.question_id=q.id;
update questions q set
stem=coalesce(t.repair->>'stem',q.stem),
choices=coalesce(t.repair->'choices',q.choices),
assets=q.assets||jsonb_build_object('answer_review','2026-09-30-independent-current-stem-review','mathematical_review_scope',t.scope)||
case when t.repair ? 'image' then jsonb_build_object('image',t.repair->>'image') else '{}'::jsonb end
from est_review_batch t where q.id=t.id;
update question_keys k set explanation=t.repair->>'explanation'
from est_review_batch t where k.question_id=t.id and t.repair ? 'explanation';
update revision_items r set fingerprint=revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation)
from questions q join question_keys k on k.question_id=q.id join est_review_revision_before b on b.question_id=q.id
where r.question_id=q.id and b.was_ready;
do $$ begin
if exists(select 1 from est_review_revision_before b join revision_items r using(question_id) where r.active is distinct from b.active) then raise exception 'Release status changed'; end if;
if (select count(*) from audit_log where action='questions.est_remaining_batch08.20260930')<>77 then raise exception 'Audit incomplete'; end if;
end $$;
commit;
